import { useState } from 'react';
import { Check, Loader2, ShieldAlert, X } from 'lucide-react';
import { useApproval, useDecideApproval } from '@/queries/approvals';
import type { Approval } from '@/types';

interface Props {
  approvalId?: string | null;
  initialData?: Record<string, unknown> | null;
  initialApproval?: Approval;
}

export function InlineApprovalCard({ approvalId, initialData, initialApproval }: Props) {
  const effectiveId = approvalId || (initialData?.approval_id ? String(initialData.approval_id) : '');
  const approvalQuery = useApproval(effectiveId || null);
  const approval = initialApproval ?? approvalQuery.data;
  const decideMutation = useDecideApproval();
  const [localDecision, setLocalDecision] = useState<'approved' | 'rejected' | null>(null);

  const toolName =
    approval?.tool_name ||
    (initialData?.tool_name ? String(initialData.tool_name) : '') ||
    (initialData?.tool ? String(initialData.tool) : '') ||
    'action_execution';

  const args =
    approval?.arguments ||
    (initialData?.arguments as Record<string, unknown>) ||
    (initialData?.args as Record<string, unknown>) ||
    {};

  const status = localDecision || approval?.status || 'pending';
  const isPending = decideMutation.isPending;

  const handleDecision = (decision: 'approved' | 'rejected') => {
    if (!effectiveId) return;
    setLocalDecision(decision);
    decideMutation.mutate(
      {
        approvalId: effectiveId,
        body: { decision },
        scope: `approval:decide:${effectiveId}:${decision}`,
      },
      {
        onError: () => {
          setLocalDecision(null);
        },
      }
    );
  };

  return (
    <div
      className="my-2 overflow-hidden rounded-[18px] border border-[var(--border-approval)] bg-[var(--surface-approval)] p-4 shadow-sm"
      style={{ boxShadow: 'var(--specular-rim)' }}
    >
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <ShieldAlert size={16} strokeWidth={2} className="shrink-0 text-amber-400" />
          <span className="text-[13px] font-semibold text-[var(--text)]">
            Action Approval Required
          </span>
        </div>
        <span className="rounded-full border border-amber-500/30 bg-amber-500/15 px-2.5 py-0.5 font-mono text-[11px] font-medium text-[var(--approval-text)]">
          {toolName}
        </span>
      </div>

      <div className="mt-3">
        <div className="text-[11px] font-medium uppercase tracking-[0.08em] text-[var(--text-muted)]">
          Tool Arguments
        </div>
        <pre className="mt-1.5 max-h-44 overflow-auto rounded-[10px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-solid)_92%,transparent)] p-2.5 font-mono text-[12px] leading-relaxed text-[var(--text)]">
          {Object.keys(args).length > 0
            ? JSON.stringify(args, null, 2)
            : '// No arguments passed'}
        </pre>
      </div>

      <div className="mt-4 flex items-center justify-between gap-2.5 pt-1">
        <span className="text-[11px] text-[var(--text-muted)]">
          {status === 'approved' ? (
            <span className="inline-flex items-center gap-1 font-medium text-emerald-400">
              <Check size={13} strokeWidth={2} /> Action Approved
            </span>
          ) : status === 'rejected' ? (
            <span className="inline-flex items-center gap-1 font-medium text-rose-400">
              <X size={13} strokeWidth={2} /> Action Rejected
            </span>
          ) : (
            'Requires your manual authorization to proceed'
          )}
        </span>

        {status === 'pending' ? (
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => handleDecision('rejected')}
              disabled={isPending || !effectiveId}
              className="btn btn-ghost h-8 px-3 text-xs font-semibold text-rose-400 hover:text-rose-300"
            >
              {isPending && localDecision === 'rejected' ? (
                <Loader2 size={13} className="animate-spin" />
              ) : (
                <X size={13} strokeWidth={2} />
              )}
              Reject
            </button>
            <button
              type="button"
              onClick={() => handleDecision('approved')}
              disabled={isPending || !effectiveId}
              className="btn btn-primary h-8 px-3 text-xs font-semibold"
            >
              {isPending && localDecision === 'approved' ? (
                <Loader2 size={13} className="animate-spin" />
              ) : (
                <Check size={13} strokeWidth={2} />
              )}
              Approve
            </button>
          </div>
        ) : null}
      </div>
    </div>
  );
}

export default InlineApprovalCard;

